mapper.update:
UPDATE im_conversation
SET last_message_id = #{messageId}, last_message_at = #{messageAt}, updated_at = #{messageAt}
WHERE id = #{conversationId} AND last_seq = #{seq}

mapper.select:
SELECT FROM sys_user u LEFT JOIN org_employee e ON e.user_id = u.id AND e.deleted = 0 LEFT JOIN sys_dept d ON d.id = COALESCE(e.dept_id, u.dept_id) AND d.deleted = 0 WHERE u.deleted = 0 AND u.status = 0 AND u.id != #{userId} AND (e.id IS NULL OR e.status IN (1, 2))
AND (COALESCE(e.name, u.nickname, u.username) LIKE CONCAT('%', #{keyword}, '%') OR e.emp_code LIKE CONCAT('%', #{keyword}, '%') OR d.dept_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY d.sort, name LIMIT #{limit}

mapper.update:
UPDATE im_message_mention mm
JOIN im_message m ON m.id = mm.message_id
SET mm.read_at = COALESCE(mm.read_at, CURRENT_TIMESTAMP(3))
WHERE mm.conversation_id = #{conversationId}
  AND mm.mentioned_user_id = #{userId}
  AND m.seq <= #{seq}
